import { bindLessonFocus } from '../../../shared/project-lessons/project-lesson-focus';
import { AutomationWeekWorkspaceComponent } from './automation-week-workspace.component';
import { WorkspaceToolsComponent } from '../../../shared/project-lessons/workspace-tools.component';
import {
  afterNextRender,
  Component,
  computed,
  effect,
  ElementRef,
  inject,
  Injector,
  signal,
  viewChild,
} from '@angular/core';
import { DecimalPipe } from '@angular/common';
import { AutomationRuntimeService } from '../runtime/automation-runtime.service';
import { RobotReplayService } from '../runtime/robot-replay.service';
import { RobotCourseComponent } from './robot-course.component';
import {
  CommandEditorComponent,
  commandLabels,
  commandDescriptions,
} from './command-editor.component';
import { CommandGraphicComponent } from './command-graphic.component';
import { TaskGuideComponent } from '../../../shared/learning/task-guide.component';
import { MathWorkbenchComponent } from './math-workbench.component';
import { AutomationEvidenceComponent } from './automation-evidence.component';
import { ChampionshipPanelComponent } from './championship-panel.component';
import type { RobotTrial } from '../domain/automation.models';
@Component({
  selector: 'app-automation-lab',
  imports: [
    AutomationWeekWorkspaceComponent,
    WorkspaceToolsComponent,
    DecimalPipe,
    RobotCourseComponent,
    CommandEditorComponent,
    MathWorkbenchComponent,
    AutomationEvidenceComponent,
    ChampionshipPanelComponent,
    CommandGraphicComponent,
    TaskGuideComponent,
  ],
  providers: [RobotReplayService],
  templateUrl: './automation-lab.component.html',
  styleUrl: './automation-lab.component.css',
})
export class AutomationLabComponent {
  readonly runtime = inject(AutomationRuntimeService);
  readonly commandLabels = commandLabels;
  readonly commandDescriptions = commandDescriptions;
  readonly replay = inject(RobotReplayService);
  readonly panel = signal<'workspace' | 'evidence' | 'portfolio' | 'championship'>('workspace');
  readonly reasoningView = signal(false);
  readonly taskPanel = viewChild<ElementRef<HTMLElement>>('taskPanel');
  readonly trace = signal(true);
  readonly replayMode = signal(false);
  private readonly injector = inject(Injector);
  readonly mathPanel = viewChild<ElementRef<HTMLElement>>('mathPanel');
  readonly courseView = viewChild<RobotCourseComponent, ElementRef<HTMLElement>>('courseView', {
    read: ElementRef,
  });
  readonly replayFinished = computed(
    () => !!this.replay.trial() && this.replay.timeMs() >= this.replay.duration(),
  );
  readonly shownCourse = computed(() =>
    this.replayMode() && this.replay.trial()
      ? this.replay.trial()!.version.course
      : this.runtime.course(),
  );
  readonly shownTarget = computed(() =>
    this.replayMode() && this.replay.trial()
      ? this.replay.trial()!.version.targetIndex
      : this.runtime.draft().targetIndex,
  );
  readonly pose = computed(() => this.replay.current() ?? this.shownCourse().startPose);
  constructor() {
    bindLessonFocus((lesson) => {
      if (this.runtime.testingWorkspace) return;
      const target = lesson.focusTarget;
      if (target === 'workspace' || target === 'evidence' || target === 'championship')
        this.panel.set(target);
    });
    effect(() => {
      if (this.panel() !== 'workspace') this.replay.pause();
    });
    effect(() => {
      const trial = this.replay.trial();
      if (this.panel() === 'workspace' && trial && this.replayFinished())
        this.runtime.observeTrial(trial.id);
    });
    if (this.runtime.sample) {
      const trial = this.runtime.currentTrials().at(-1);
      if (trial) {
        this.replay.load(trial);
        this.replayMode.set(true);
        this.replay.seek(this.replay.duration());
      }
    }
  }
  choose(id: string): void {
    this.edit();
    this.runtime.selectChallenge(id);
    if (this.runtime.sample) {
      const trial = this.runtime.currentTrials().at(-1);
      if (trial) {
        this.replay.load(trial);
        this.replayMode.set(true);
        this.replay.seek(this.replay.duration());
      }
    }
  }
  run(): void {
    const trial = this.runtime.runPractice();
    if (trial) this.showTrial(trial);
  }
  openReasoning(): void {
    this.runtime.openReasoning();
    if (!this.runtime.reasoningOpened()) return;
    this.replay.pause();
    this.reasoningView.set(true);
    afterNextRender(
      () => {
        const panel = this.mathPanel()?.nativeElement;
        panel?.querySelector('h2')?.scrollIntoView({ block: 'nearest' });
        panel?.focus({ preventScroll: true });
      },
      { injector: this.injector },
    );
  }
  watchLatest(): void {
    const trial = this.runtime
      .currentTrials()
      .filter((t) => t.mode === 'practice')
      .at(-1);
    if (trial) this.showTrial(trial);
  }
  showTrial(trial: RobotTrial): void {
    this.reasoningView.set(false);
    if (this.runtime.challenge().id !== trial.challengeId)
      this.runtime.selectChallenge(trial.challengeId);
    this.replayMode.set(true);
    this.replay.load(
      trial,
      !(typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches),
    );
    this.panel.set('workspace');
    afterNextRender(
      () => {
        const course = this.courseView()?.nativeElement;
        course?.scrollIntoView({ block: 'nearest' });
        course?.focus({ preventScroll: true });
      },
      { injector: this.injector },
    );
  }
  edit(): void {
    this.replay.pause();
    this.replay.timeMs.set(0);
    this.replay.trial.set(undefined);
    this.replayMode.set(false);
    this.reasoningView.set(false);
    afterNextRender(
      () => {
        const task = this.taskPanel()?.nativeElement;
        task?.scrollIntoView({ block: 'nearest' });
        task
          ?.querySelector<HTMLElement>('input:not(:disabled), button')
          ?.focus({ preventScroll: true });
      },
      { injector: this.injector },
    );
  }
  changeTarget(index: string): void {
    this.edit();
    this.runtime.setTarget(Number(index));
  }
}
